/// The nested `MessageExtendedMedia::Type` (MessageExtendedMedia.h:13).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub enum MessageExtendedMediaType {
    #[default]
    Empty,
    Unsupported,
    Preview,
    Photo,
    Video,
}

/// `td::MessageExtendedMedia` (MessageExtendedMedia.h:12-36) — the C++
/// tagged fields flattened; the wire/td_api constructors and the
/// file-id/merge helpers land with their slices.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct MessageExtendedMedia {
    pub r#type: MessageExtendedMediaType,
    pub unsupported_version: i32,
    pub duration: i32,
    pub dimensions: Dimensions,
    pub minithumbnail: String,
    pub photo: Photo,
    pub video_file_id: FileId,
    pub start_timestamp: i32,
}

impl MessageExtendedMedia {
    /// `MessageExtendedMedia::CURRENT_VERSION` (MessageExtendedMedia.h:16).
    pub const CURRENT_VERSION: i32 = 1;

    /// `MessageExtendedMedia::is_empty` (MessageExtendedMedia.h).
    pub fn is_empty(&self) -> bool {
        self.r#type == MessageExtendedMediaType::Empty
    }

    /// `MessageExtendedMedia::has_input_media` (MessageExtendedMedia.h).
    pub fn has_input_media(&self) -> bool {
        self.r#type == MessageExtendedMediaType::Photo
            || self.r#type == MessageExtendedMediaType::Video
    }

    /// `MessageExtendedMedia::is_unsupported` (MessageExtendedMedia.h).
    pub fn is_unsupported(&self) -> bool {
        self.r#type == MessageExtendedMediaType::Unsupported
    }

    /// `MessageExtendedMedia::is_media` (MessageExtendedMedia.h:53-55).
    pub fn is_media(&self) -> bool {
        self.r#type != MessageExtendedMediaType::Empty
            && self.r#type != MessageExtendedMediaType::Preview
    }

    /// `MessageExtendedMedia::update_from` (MessageExtendedMedia.cpp:218-222)
    /// — an old media value fills a not-yet-loaded slot.
    pub fn update_from(&mut self, old_extended_media: &MessageExtendedMedia) {
        if !self.is_media() && old_extended_media.is_media() {
            *self = old_extended_media.clone();
        }
    }

    /// `MessageExtendedMedia::is_equal_but_different`
    /// (MessageExtendedMedia.cpp:449-452).
    pub fn is_equal_but_different(&self, other: &MessageExtendedMedia) -> bool {
        self.r#type == MessageExtendedMediaType::Unsupported
            && other.r#type == MessageExtendedMediaType::Unsupported
            && self.unsupported_version != other.unsupported_version
    }

    /// `MessageExtendedMedia::get_any_file_id` (MessageExtendedMedia.cpp:324-336).
    pub fn get_any_file_id(&self) -> FileId {
        match self.r#type {
            MessageExtendedMediaType::Photo => crate::photo::get_photo_any_file_id(&self.photo),
            MessageExtendedMediaType::Video => self.video_file_id,
            MessageExtendedMediaType::Empty
            | MessageExtendedMediaType::Unsupported
            | MessageExtendedMediaType::Preview => FileId::default(),
        }
    }

    /// `MessageExtendedMedia::update_file_id_remote`
    /// (MessageExtendedMedia.cpp:375-382).
    pub fn update_file_id_remote(&mut self, file_id: FileId) {
        if file_id.get_remote() == 0 || self.r#type != MessageExtendedMediaType::Video {
            return;
        }
        if self.video_file_id == file_id && self.video_file_id.get_remote() == 0 {
            self.video_file_id = file_id;
        }
    }

    /// `MessageExtendedMedia::merge_files` (MessageExtendedMedia.cpp:429-447).
    pub fn merge_files(
        &self,
        td: &mut dyn MessageContentContext,
        other: &mut MessageExtendedMedia,
        dialog_id: DialogId,
        need_merge_files: bool,
        is_content_changed: &mut bool,
        need_update: &mut bool,
    ) {
        if !self.has_input_media() || !other.has_input_media() {
            return;
        }
        if self.r#type != other.r#type {
            tdutils::log_error!("Type of paid media has changed");
            return;
        }
        match self.r#type {
            MessageExtendedMediaType::Photo => {
                merge_photos(
                    td,
                    &self.photo,
                    &mut other.photo,
                    dialog_id,
                    need_merge_files,
                    is_content_changed,
                    need_update,
                );
            }
            MessageExtendedMediaType::Video => {
                if self.video_file_id != other.video_file_id && need_merge_files {
                    td.merge_videos(other.video_file_id, self.video_file_id);
                }
            }
            MessageExtendedMediaType::Empty
            | MessageExtendedMediaType::Preview
            | MessageExtendedMediaType::Unsupported => {
                // the C++ `default:` arm is `UNREACHABLE()` — abort the same way.
                unreachable!("Unexpected paid media type to merge");
            }
        }
    }

    /// `MessageExtendedMedia::need_reget` (MessageExtendedMedia.h).
    pub fn need_reget(&self) -> bool {
        self.r#type == MessageExtendedMediaType::Unsupported
            && self.unsupported_version < Self::CURRENT_VERSION
    }

    /// `MessageExtendedMedia::need_poll` (MessageExtendedMedia.h).
    pub fn need_poll(&self) -> bool {
        self.r#type == MessageExtendedMediaType::Preview
    }

    /// `MessageExtendedMedia::has_media_timestamp` (MessageExtendedMedia.h).
    pub fn has_media_timestamp(&self) -> bool {
        self.r#type == MessageExtendedMediaType::Video
    }

    /// `MessageExtendedMedia::get_message_content` (MessageExtendedMedia.cpp)
    /// — the per-type content the paid-media album splat produces. The C++
    /// `default: UNREACHABLE()` covers Empty/Unsupported/Preview, which the
    /// caller (`get_individual_message_contents`) never sees for a real
    /// paid media.
    pub fn get_message_content(&self) -> MessageContent {
        match self.r#type {
            MessageExtendedMediaType::Photo => {
                create_photo_message_content(self.photo.clone(), self.video_file_id)
            }
            MessageExtendedMediaType::Video => create_video_message_content(
                self.video_file_id,
                self.photo.clone(),
                self.start_timestamp,
            ),
            MessageExtendedMediaType::Empty
            | MessageExtendedMediaType::Unsupported
            | MessageExtendedMediaType::Preview => {
                unreachable!()
            }
        }
    }

    /// `MessageExtendedMedia::get_input_media` (MessageExtendedMedia.cpp:409-427).
    pub fn get_input_media(
        &self,
        td: &dyn MessageContentContext,
        input_file: Option<telegram_api::InputFile>,
        input_thumbnail: Option<telegram_api::InputFile>,
    ) -> Option<telegram_api::InputMedia> {
        match self.r#type {
            MessageExtendedMediaType::Photo => {
                td.photo_get_input_media(&self.photo, input_file, 0, false, self.video_file_id)
            }
            MessageExtendedMediaType::Video => td.get_video_input_media(
                self.video_file_id,
                input_file,
                input_thumbnail,
                &self.photo,
                self.start_timestamp,
                0,
                false,
            ),
            MessageExtendedMediaType::Empty
            | MessageExtendedMediaType::Unsupported
            | MessageExtendedMediaType::Preview => None,
        }
    }

    /// `MessageExtendedMedia::delete_thumbnail` (MessageExtendedMedia.cpp:284-300).
    pub fn delete_thumbnail(&mut self, td: &mut dyn MessageContentContext) {
        match self.r#type {
            MessageExtendedMediaType::Photo => photo_delete_thumbnail(&mut self.photo),
            MessageExtendedMediaType::Video => td.delete_video_thumbnail(self.video_file_id),
            MessageExtendedMediaType::Empty
            | MessageExtendedMediaType::Unsupported
            | MessageExtendedMediaType::Preview => {}
        }
    }
}

impl InputInvoice {
    /// `InputInvoice::has_media_timestamp` (InputInvoice.cpp).
    pub fn has_media_timestamp(&self) -> bool {
        self.extended_media.has_media_timestamp()
    }

    /// `InputInvoice::update_from` (InputInvoice.cpp:387-389) — keep the
    /// old media when the new invoice has none.
    pub fn update_from(&mut self, old_input_invoice: &InputInvoice) {
        self.extended_media
            .update_from(&old_input_invoice.extended_media);
    }

    /// `InputInvoice::get_any_file_id` (InputInvoice.cpp:379-381).
    pub fn get_any_file_id(&self) -> FileId {
        self.extended_media.get_any_file_id()
    }

    /// `InputInvoice::get_caption` (InputInvoice.cpp) — the caption of the
    /// extended media, never null.
    pub fn get_caption(&self) -> &FormattedText {
        &self.extended_media_caption
    }

    /// `InputInvoice::get_input_media_invoice` (InputInvoice.cpp:302-330).
    /// The `get_input_web_document` read goes through the seam (the
    /// M.12.2 FileManager); a null web document leaves the PHOTO flag
    /// unset exactly like the C++.
    pub fn get_input_media_invoice(
        &self,
        td: &dyn MessageContentContext,
        input_file: Option<telegram_api::InputFile>,
        input_thumbnail: Option<telegram_api::InputFile>,
    ) -> Option<telegram_api::InputMedia> {
        let mut flags = 0;
        if !self.start_parameter.is_empty() {
            flags |= 1 << 1; // START_PARAM_MASK
        }
        let input_web_document = td.get_input_web_document(&self.photo);
        if input_web_document.is_some() {
            flags |= 1 << 0; // PHOTO_MASK
        }
        let mut extended_media = None;
        if !self.extended_media.is_empty() {
            flags |= 1 << 2; // EXTENDED_MEDIA_MASK
            extended_media = self
                .extended_media
                .get_input_media(td, input_file, input_thumbnail);
            extended_media.as_ref()?;
        }
        if !self.provider_token.is_empty() {
            flags |= 1 << 3; // PROVIDER_MASK
        }
        Some(telegram_api::InputMedia::inputMediaInvoice(
            telegram_api::inputMediaInvoice {
                flags,
                title: self.title.clone(),
                description: self.description.clone(),
                photo: input_web_document,
                invoice: Some(self.invoice.get_input_invoice()),
                payload: self.payload.as_bytes().to_vec(),
                provider: self.provider_token.clone(),
                provider_data: Some(telegram_api::DataJSON {
                    data: if self.provider_data.is_empty() {
                        "null".to_owned()
                    } else {
                        self.provider_data.clone()
                    },
                }),
                start_param: self.start_parameter.clone(),
                extended_media: extended_media.map(Box::new),
            },
        ))
    }

    /// `InputInvoice::delete_thumbnail` (InputInvoice.cpp:355-357).
    pub fn delete_thumbnail(&mut self, td: &mut dyn MessageContentContext) {
        self.extended_media.delete_thumbnail(td);
    }
}

