    /// The `MessageText` constructor flag normalization
    /// (MessageContent.cpp:170-176).
    #[test]
    fn text_flags_normalize_without_a_web_page_url() {
        let no_url = MessageText::new(
            FormattedText::default(),
            WebPageId::default(),
            true,
            true,
            false,
            String::new(),
        );
        assert!(!no_url.force_small_media);
        assert!(!no_url.force_large_media);

        let large = MessageText::new(
            FormattedText::default(),
            WebPageId::new(-1),
            true,
            true,
            false,
            "https://telegram.org".to_string(),
        );
        assert!(!large.force_small_media);
        assert!(large.force_large_media);

        let small = MessageText::new(
            FormattedText::default(),
            WebPageId::new(-1),
            true,
            false,
            false,
            "https://telegram.org".to_string(),
        );
        assert!(small.force_small_media);
        assert!(!small.force_large_media);
    }

    /// The `MessageDice` constructor normalization and the `is_valid`
    /// decision table (MessageContent.cpp:787-825).
    #[test]
    fn dice_emoji_normalizes_and_validates() {
        let default_emoji = MessageDice::new("", 3, false, Vec::new(), String::new(), 0, 0);
        assert_eq!(default_emoji.emoji, MessageDice::DEFAULT_EMOJI);

        // The C++ default `remove_selectors = true`.
        let stripped = MessageDice::new("🎲\u{fe0f}", 3, false, Vec::new(), String::new(), 0, 0);
        assert_eq!(stripped.emoji, MessageDice::DEFAULT_EMOJI);

        assert!(
            MessageDice::new(
                MessageDice::DEFAULT_EMOJI,
                6,
                false,
                Vec::new(),
                String::new(),
                0,
                0
            )
            .is_valid()
        );
        assert!(
            !MessageDice::new(
                MessageDice::DEFAULT_EMOJI,
                7,
                false,
                Vec::new(),
                String::new(),
                0,
                0
            )
            .is_valid()
        );
        assert!(MessageDice::new("🎯", 6, false, Vec::new(), String::new(), 0, 0).is_valid());
        assert!(!MessageDice::new("🎯", 7, false, Vec::new(), String::new(), 0, 0).is_valid());
        assert!(MessageDice::new("⚽", 1000, false, Vec::new(), String::new(), 0, 0).is_valid());
        assert!(!MessageDice::new("⚽", 1001, false, Vec::new(), String::new(), 0, 0).is_valid());
        assert!(!MessageDice::new("⚽", -1, false, Vec::new(), String::new(), 0, 0).is_valid());

        // A stake with a value needs the default die, a seed and a positive
        // stake amount.
        assert!(
            MessageDice::new(
                MessageDice::DEFAULT_EMOJI,
                3,
                true,
                b"seed".to_vec(),
                String::new(),
                10,
                0
            )
            .is_valid()
        );
        assert!(
            !MessageDice::new("⚽", 3, true, b"seed".to_vec(), String::new(), 10, 0).is_valid()
        );
        assert!(
            !MessageDice::new(
                MessageDice::DEFAULT_EMOJI,
                3,
                true,
                Vec::new(),
                String::new(),
                10,
                0
            )
            .is_valid()
        );
        assert!(
            !MessageDice::new(
                MessageDice::DEFAULT_EMOJI,
                3,
                true,
                b"seed".to_vec(),
                String::new(),
                0,
                0
            )
            .is_valid()
        );
        assert!(
            !MessageDice::new(
                MessageDice::DEFAULT_EMOJI,
                3,
                true,
                b"seed".to_vec(),
                String::new(),
                10,
                -1
            )
            .is_valid()
        );

        // A stake without a value needs a state hash and a 32-byte seed.
        assert!(
            MessageDice::new(
                MessageDice::DEFAULT_EMOJI,
                0,
                true,
                b"01234567890123456789012345678901".to_vec(),
                "state".to_string(),
                0,
                0
            )
            .is_valid()
        );
        assert!(
            !MessageDice::new(
                MessageDice::DEFAULT_EMOJI,
                0,
                true,
                b"0123456789012345678901234567890123456789".to_vec(),
                "state".to_string(),
                0,
                0
            )
            .is_valid()
        );
        assert!(
            !MessageDice::new(
                MessageDice::DEFAULT_EMOJI,
                0,
                true,
                b"short seed".to_vec(),
                "state".to_string(),
                0,
                0
            )
            .is_valid()
        );
    }

