    /// The `MessageContentContext` stand-in: a permission table over a
    /// restricted rights word, plus flags for the manager seams the
    /// policy plane reads. Manager reads without a test default
    /// `log_error!` and answer like an empty manager would.
    struct TestContext {
        rights: RestrictedRights,
        is_bot: bool,
        my_dialog_id: DialogId,
        broadcast: bool,
        monoforum: bool,
        voice_forbidden: bool,
        poll_anonymous: bool,
        sticker_type: StickerType,
        web_page_user_ids: Vec<UserId>,
        web_page_channel_ids: Vec<ChannelId>,
        poll_input_media: bool,
        poll_can_add_option: bool,
        checklist_max: i64,
        poll_contents: Vec<MessageContent>,
        poll_contents_2: Vec<MessageContent>,
        have_web_pages: Vec<WebPageId>,
        always_parse_markdown: bool,
        secret_chat_layer: i32,
        secret_chat_user_id: UserId,
        premium_custom_emoji: bool,
        dialog_premium: bool,
        channel_can_add_web_page_previews: bool,
        web_page_by_url: WebPageId,
        known_users: Vec<UserId>,
        my_id: UserId,
        checklist_title_max: i64,
        checklist_task_text_max: i64,
        paid_media_star_count_max: i64,
        poll_country_count_max: i64,
        poll_answer_count_max: i64,
        file_view_details: HashMap<FileId, (String, String, String)>,
        input_file_counter: i32,
        poll_counter: i64,
        known_stories: Vec<StoryFullId>,
        read_access_dialogs: Vec<DialogId>,
        register_log: Vec<String>,
        authorized: bool,
        on_get_poll_id: PollId,
    }

