        fn create_poll(
            &mut self,
            question: FormattedText,
            options: Vec<PollOption>,
            is_anonymous: bool,
            allows_multiple_answers: bool,
            has_open_answers: bool,
            fixed_answers: bool,
            members_only: bool,
            country_codes: Vec<String>,
            shuffle_options: bool,
            hide_results_until_closes: bool,
            is_quiz: bool,
            correct_option_ids: Vec<i32>,
            explanation: FormattedText,
            _explanation_media: Option<Box<MessageContent>>,
            open_period: i32,
            close_date: i32,
            is_closed: bool,
        ) -> PollId {
            self.poll_counter += 1;
            self.register_log.push(format!(
                "create_poll({},{},{},{},{},{},{},{:?},{},{},{},{:?},{},{},{},{},{})",
                question.text,
                options.len(),
                is_anonymous,
                allows_multiple_answers,
                has_open_answers,
                fixed_answers,
                members_only,
                country_codes,
                shuffle_options,
                hide_results_until_closes,
                is_quiz,
                correct_option_ids,
                explanation.text,
                open_period,
                close_date,
                is_closed,
                self.poll_counter
            ));
            PollId::new(self.poll_counter)
        }

