    #[test]
    fn get_to_do_list_validates() {
        let td = TestContext::default();
        let dialog_id = DialogId::from_user_id(UserId::new(7));
        let list = td_api::InputChecklist {
            title: Some(td_api_text("checklist")),
            tasks: vec![td_api::InputChecklistTask {
                id: 1,
                text: Some(td_api_text("task 1")),
            }],
            others_can_add_tasks: true,
            others_can_mark_tasks_as_done: false,
        };
        let result = get_to_do_list(&td, dialog_id, Some(list)).unwrap();
        assert_eq!(result.title.text, "checklist");
        assert_eq!(result.items.len(), 1);
        assert!(result.others_can_append);
        assert!(!result.others_can_complete);

        // no tasks is rejected
        let error = get_to_do_list(
            &td,
            dialog_id,
            Some(td_api::InputChecklist {
                title: Some(td_api_text("checklist")),
                tasks: vec![],
                others_can_add_tasks: false,
                others_can_mark_tasks_as_done: false,
            }),
        )
        .unwrap_err();
        assert_eq!(error.message(), "Checklist must have at least 1 task");

        // a missing checklist is rejected
        let error = get_to_do_list(&td, dialog_id, None).unwrap_err();
        assert_eq!(error.message(), "Checklist must be non-empty");
    }

    #[test]
    fn extract_input_caption_and_invert_media_table() {
        let mut input = td_api::InputMessageContent::inputMessagePhoto(td_api::inputMessagePhoto {
            caption: Some(td_api_text("cap")),
            show_caption_above_media: true,
            ..td_api::inputMessagePhoto::default()
        });
        assert_eq!(
            extract_input_caption(&mut input).unwrap().text,
            "cap".to_string()
        );
        assert!(extract_input_invert_media(&input));

        // the caption is taken out
        let td_api::InputMessageContent::inputMessagePhoto(input_photo) = input else {
            panic!()
        };
        assert!(input_photo.caption.is_none());

        let mut input = td_api::InputMessageContent::inputMessageText(td_api::inputMessageText {
            text: Some(td_api_text("hello")),
            link_preview_options: None,
            clear_draft: false,
        });
        assert!(extract_input_caption(&mut input).is_none());
        assert!(!extract_input_invert_media(&input));
    }

    fn input_td() -> TestContext {
        TestContext {
            file_view_details: HashMap::from([(
                FileId::new(5, 0),
                (
                    "movie.mp4".to_string(),
                    "video/mp4".to_string(),
                    "mp4".to_string(),
                ),
            )]),
            known_users: vec![UserId::new(9)],
            ..TestContext::default()
        }
    }

    fn input_file_id() -> FileId {
        FileId::new(5, 0)
    }

    #[test]
    fn create_input_message_content_builds_the_pure_arms() {
        let user_dialog = DialogId::from_user_id(UserId::new(7));
        let caption = FormattedText::default();
        let no_file = FileId::default();
        let no_thumbnail = PhotoSize::default();

        // text
        let mut td = input_td();
        let result = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessageText(td_api::inputMessageText {
                text: Some(td_api_text("hello")),
                link_preview_options: None,
                clear_draft: true,
            }),
            caption.clone(),
            no_file,
            no_thumbnail.clone(),
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(&*result.content, MessageContent::Text(_)));
        assert!(result.clear_draft);

        // dice
        let result = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessageDice(td_api::inputMessageDice {
                emoji: "🎯".to_string(),
                clear_draft: false,
            }),
            caption.clone(),
            no_file,
            no_thumbnail.clone(),
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(
            &*result.content,
            MessageContent::Dice(d) if d.emoji == "🎯" && d.dice_value == 0
        ));

        // stake dice carries a 32-byte random seed and the state hash
        let result = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessageStakeDice(td_api::inputMessageStakeDice {
                state_hash: "hash".to_string(),
                stake_gram_amount: 10,
                clear_draft: true,
            }),
            caption.clone(),
            no_file,
            no_thumbnail.clone(),
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(
            &*result.content,
            MessageContent::Dice(d)
                if d.is_stake
                    && d.seed.len() == 32
                    && d.stake_ton_count == 10
                    && d.prize_ton_count == -1
        ));
        assert!(result.clear_draft);

        // an empty state hash is rejected
        let error = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessageStakeDice(td_api::inputMessageStakeDice {
                state_hash: String::new(),
                stake_gram_amount: 10,
                clear_draft: false,
            }),
            caption.clone(),
            no_file,
            no_thumbnail.clone(),
            vec![],
            false,
        )
        .unwrap_err();
        assert_eq!(error.message(), "State hash must be non-empty");

        // location
        let result = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessageLocation(td_api::inputMessageLocation {
                location: Some(td_api::Location {
                    latitude: 1.0,
                    longitude: 2.0,
                    horizontal_accuracy: 0.0,
                }),
            }),
            caption.clone(),
            no_file,
            no_thumbnail.clone(),
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(&*result.content, MessageContent::Location(_)));

        // game sets the via bot user id, cleared for my own id
        let result = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessageGame(td_api::inputMessageGame {
                bot_user_id: 9,
                game_short_name: "chess".to_string(),
            }),
            caption.clone(),
            no_file,
            no_thumbnail,
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(&*result.content, MessageContent::Game(_)));
        assert_eq!(result.via_bot_user_id, UserId::new(9));
    }

    #[test]
    fn create_input_message_content_routes_the_media_arms() {
        let user_dialog = DialogId::from_user_id(UserId::new(7));
        let caption = FormattedText::default();
        let file_id = input_file_id();
        let thumbnail = PhotoSize {
            size_type: 't' as i32,
            file_id: FileId::new(8, 0),
            ..PhotoSize::default()
        };

        // animation
        let mut td = input_td();
        let result = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessageAnimation(td_api::inputMessageAnimation {
                animation: Some(td_api::InputAnimation {
                    animation: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                        id: 42,
                    })),
                    duration: 7,
                    width: 640,
                    height: 480,
                    ..td_api::InputAnimation::default()
                }),
                show_caption_above_media: true,
                ..td_api::inputMessageAnimation::default()
            }),
            caption,
            file_id,
            thumbnail.clone(),
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(
            &*result.content,
            MessageContent::Animation(m) if m.file_id == file_id && !m.has_spoiler
        ));
        assert!(result.invert_media);
        assert_eq!(
            td.register_log,
            vec!["create_animation(5,8,false,[],movie.mp4,video/mp4,7,640,480)"]
        );

        // audio rides the create_audio seam
        let result = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessageAudio(td_api::inputMessageAudio {
                audio: Some(td_api::InputAudio {
                    title: "Song".to_string(),
                    performer: "Artist".to_string(),
                    duration: 120,
                    ..td_api::InputAudio::default()
                }),
                ..td_api::inputMessageAudio::default()
            }),
            FormattedText::default(),
            file_id,
            thumbnail.clone(),
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(&*result.content, MessageContent::Audio(_)));
        assert_eq!(
            td.register_log.last().map(String::as_str),
            Some("create_audio(5,8,movie.mp4,video/mp4,120,Song,Artist)")
        );

        // video: cover + video creation, spoiler masked in secret chats
        let mut td = input_td();
        let secret_dialog = DialogId::from_secret_chat_id(SecretChatId::new(3));
        let result = create_input_message_content(
            &mut td,
            secret_dialog,
            td_api::InputMessageContent::inputMessageVideo(td_api::inputMessageVideo {
                video: Some(td_api::InputVideo {
                    video: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                        id: 42,
                    })),
                    duration: 10,
                    width: 320,
                    height: 240,
                    supports_streaming: true,
                    ..td_api::InputVideo::default()
                }),
                has_spoiler: true,
                ..td_api::inputMessageVideo::default()
            }),
            FormattedText::default(),
            file_id,
            thumbnail,
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(
            &*result.content,
            MessageContent::Video(m) if !m.has_spoiler && m.start_timestamp == 0
        ));
        let video_created = td
            .register_log
            .iter()
            .any(|entry| entry.contains("create_video(5"));
        assert!(video_created);

        // a too-long video note is rejected
        let error = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessageVideoNote(td_api::inputMessageVideoNote {
                video_note: Some(td_api::InputVideoNote {
                    length: 641,
                    ..td_api::InputVideoNote::default()
                }),
                ..td_api::inputMessageVideoNote::default()
            }),
            FormattedText::default(),
            file_id,
            PhotoSize::default(),
            vec![],
            false,
        )
        .unwrap_err();
        assert_eq!(error.message(), "Wrong video note length");
    }

    #[test]
    fn create_input_message_content_photo_and_ttl_paths() {
        let user_dialog = DialogId::from_user_id(UserId::new(7));
        let file_id = input_file_id();

        // a plain photo
        let mut td = input_td();
        let result = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessagePhoto(td_api::inputMessagePhoto {
                photo: Some(td_api::InputPhoto {
                    photo: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                        id: 42,
                    })),
                    width: 100,
                    height: 200,
                    ..td_api::InputPhoto::default()
                }),
                has_spoiler: true,
                ..td_api::inputMessagePhoto::default()
            }),
            FormattedText::default(),
            file_id,
            PhotoSize::default(),
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(
            &*result.content,
            MessageContent::Photo(m) if m.has_spoiler
        ));
        let photo_created = td
            .register_log
            .iter()
            .any(|entry| entry.contains("create_photo_input(5"));
        assert!(photo_created);

        // a live photo registers the video file id through the seam
        let mut td = input_td();
        let result = create_input_message_content(
            &mut td,
            user_dialog,
            td_api::InputMessageContent::inputMessagePhoto(td_api::inputMessagePhoto {
                photo: Some(td_api::InputPhoto {
                    photo: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                        id: 42,
                    })),
                    video: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                        id: 43,
                    })),
                    width: 100,
                    height: 200,
                    ..td_api::InputPhoto::default()
                }),
                ..td_api::inputMessagePhoto::default()
            }),
            FormattedText::default(),
            file_id,
            PhotoSize::default(),
            vec![],
            false,
        )
        .unwrap();
        assert!(matches!(
            &*result.content,
            MessageContent::Photo(m) if m.video_file_id.is_valid()
        ));
        let live_photo_registered = td
            .register_log
            .iter()
            .any(|entry| entry.contains("get_input_file_id(LivePhoto)"));
        assert!(live_photo_registered);

        // self-destruct only in private chats
        let chat_dialog = DialogId::from_chat_id(ChatId::new(4));
        let error = create_input_message_content(
            &mut td,
            chat_dialog,
            td_api::InputMessageContent::inputMessagePhoto(td_api::inputMessagePhoto {
                photo: Some(td_api::InputPhoto {
                    photo: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                        id: 42,
                    })),
                    ..td_api::InputPhoto::default()
                }),
                self_destruct_type: Some(
                    td_api::MessageSelfDestructType::messageSelfDestructTypeTimer(
                        td_api::messageSelfDestructTypeTimer {
                            self_destruct_time: 30,
                        },
                    ),
                ),
                ..td_api::inputMessagePhoto::default()
            }),
            FormattedText::default(),
            file_id,
            PhotoSize::default(),
            vec![],
            false,
        )
        .unwrap_err();
        assert_eq!(
            error.message(),
            "Messages can self-destruct only in private chats"
        );

        // the deferred arms reject with the recorded interim errors
        for input in [
            td_api::InputMessageContent::inputMessagePoll(td_api::inputMessagePoll {
                ..td_api::inputMessagePoll::default()
            }),
            td_api::InputMessageContent::inputMessageInvoice(td_api::inputMessageInvoice {
                ..td_api::inputMessageInvoice::default()
            }),
        ] {
            let error = create_input_message_content(
                &mut td,
                user_dialog,
                input,
                FormattedText::default(),
                file_id,
                PhotoSize::default(),
                vec![],
                false,
            )
            .unwrap_err();
            assert_eq!(error.code(), 400);
        }
    }

    #[test]
    fn get_message_extended_media_validates_and_builds() {
        let dialog_id = DialogId::from_user_id(UserId::new(7));

        // a missing paid media is an empty medium
        let mut td = TestContext::default();
        assert!(
            get_message_extended_media(&mut td, None, dialog_id)
                .unwrap()
                .is_empty()
        );

        // an invalid owner dialog is rejected
        let error = get_message_extended_media(
            &mut td,
            Some(td_api::InputPaidMedia {
                ..td_api::InputPaidMedia::default()
            }),
            DialogId::default(),
        )
        .unwrap_err();
        assert_eq!(
            error.message(),
            "Extended media can't be added to the invoice"
        );

        // a missing type is rejected
        let error = get_message_extended_media(
            &mut td,
            Some(td_api::InputPaidMedia {
                ..td_api::InputPaidMedia::default()
            }),
            dialog_id,
        )
        .unwrap_err();
        assert_eq!(error.message(), "Paid media type must be non-empty");

        // a photo medium
        let mut td = TestContext::default();
        let media = get_message_extended_media(
            &mut td,
            Some(td_api::InputPaidMedia {
                r#type: Some(td_api::InputPaidMediaType::inputPaidMediaTypePhoto(
                    td_api::inputPaidMediaTypePhoto { video: None },
                )),
                media: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                    id: 42,
                })),
                width: 100,
                height: 200,
                ..td_api::InputPaidMedia::default()
            }),
            dialog_id,
        )
        .unwrap();
        assert_eq!(media.r#type, MessageExtendedMediaType::Photo);
        assert!(!media.photo.photos.is_empty());
        assert!(!media.video_file_id.is_valid());

        // a video medium with a cover
        let mut td = input_td();
        let media = get_message_extended_media(
            &mut td,
            Some(td_api::InputPaidMedia {
                r#type: Some(td_api::InputPaidMediaType::inputPaidMediaTypeVideo(
                    td_api::inputPaidMediaTypeVideo {
                        cover: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                            id: 43,
                        })),
                        start_timestamp: -5,
                        duration: 9,
                        supports_streaming: true,
                    },
                )),
                media: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                    id: 42,
                })),
                width: 100,
                height: 200,
                ..td_api::InputPaidMedia::default()
            }),
            dialog_id,
        )
        .unwrap();
        assert_eq!(media.r#type, MessageExtendedMediaType::Video);
        assert!(media.video_file_id.is_valid());
        assert_eq!(media.start_timestamp, 0);
    }

    #[test]
    fn process_input_message_invoice_validates_and_builds() {
        let dialog_id = DialogId::from_user_id(UserId::new(7));
        let valid_invoice = || {
            td_api::InputMessageContent::inputMessageInvoice(td_api::inputMessageInvoice {
                invoice: Some(td_api::Invoice {
                    currency: "USD".to_string(),
                    price_parts: vec![td_api::LabeledPricePart {
                        label: "item".to_string(),
                        amount: 100,
                    }],
                    ..td_api::Invoice::default()
                }),
                title: "Thing".to_string(),
                description: "A thing".to_string(),
                photo_url: String::new(),
                start_parameter: String::new(),
                provider_token: "token".to_string(),
                provider_data: String::new(),
                payload: vec![1, 2, 3],
                paid_media: None,
                paid_media_caption: None,
                ..td_api::inputMessageInvoice::default()
            })
        };

        let mut td = TestContext::default();
        let result = process_input_message_invoice(&mut td, valid_invoice(), dialog_id).unwrap();
        assert_eq!(result.title, "Thing");
        assert_eq!(result.invoice.currency, "USD");
        assert_eq!(result.total_amount, 100);
        assert_eq!(result.payload, "\u{1}\u{2}\u{3}");

        // a missing invoice is rejected
        let error = process_input_message_invoice(
            &mut td,
            td_api::InputMessageContent::inputMessageInvoice(td_api::inputMessageInvoice {
                invoice: None,
                ..td_api::inputMessageInvoice::default()
            }),
            dialog_id,
        )
        .unwrap_err();
        assert_eq!(error.message(), "Invoice must be non-empty");

        // empty price parts are rejected
        let error = process_input_message_invoice(
            &mut td,
            td_api::InputMessageContent::inputMessageInvoice(td_api::inputMessageInvoice {
                invoice: Some(td_api::Invoice {
                    currency: "USD".to_string(),
                    price_parts: vec![],
                    ..td_api::Invoice::default()
                }),
                ..td_api::inputMessageInvoice::default()
            }),
            dialog_id,
        )
        .unwrap_err();
        assert_eq!(error.message(), "There must be at least one price part");

        // a too-big tip is rejected
        let error = process_input_message_invoice(
            &mut td,
            td_api::InputMessageContent::inputMessageInvoice(td_api::inputMessageInvoice {
                invoice: Some(td_api::Invoice {
                    currency: "USD".to_string(),
                    price_parts: vec![td_api::LabeledPricePart {
                        label: "item".to_string(),
                        amount: 100,
                    }],
                    max_tip_amount: 50,
                    suggested_tip_amounts: vec![100],
                    ..td_api::Invoice::default()
                }),
                ..td_api::inputMessageInvoice::default()
            }),
            dialog_id,
        )
        .unwrap_err();
        assert_eq!(
            error.message(),
            "Suggested tip amount can't be bigger than max_tip_amount"
        );
    }

